src/api.ts:
export function apiUrl(path) {
  return process.env.API_BASE_URL + path;
}

src/report/summary.ts:
export function buildSummary(rows, title) {
  const heading = `Summary: ${title}`;
  const totals = { count: 0, amount: 0, flagged: 0 };
  for (const row of rows) {
    totals.count += 1;
    totals.amount += row.amount;
    if (row.flagged) {
      totals.flagged += 1;
    }
  }
  const average = totals.count ? totals.amount / totals.count : 0;
  const lines = [`count: ${totals.count}`, `amount: ${totals.amount}`];
  lines.push(`average: ${average.toFixed(2)}`);
  lines.push(`flagged: ${totals.flagged}`);
  return [heading, ...lines].join("\n");
}

